if wantenter('DUNGEON OF EVIL') then begin
              if party.etc[44] and bit2 = 0 then begin
                 enemynumber := 7;
                 for i := 1 to 7 do joinenemy(i,62);
                 joinenemy(3,70);
                 displayenemies(TRUE);
                 Print(13,' 이 동굴에 들어 가겠다고?');
                 Print(13,' 하!, 우습군. 너희들에게는 여기의 Draconian');
                 Print(13,'족들의 모습이 보이지 않는 모양이군.');
                 PressAnyKey;
                 if player[6].name = 'Draconian' then begin
                    Print(7,' ArchiDraconian은 마지막에 있는 Draconian');
                    Print(7,'을 발견했다.');
                    Print(13,' 아니 너는 누구냐! 감히 Draconian 족이면');
                    Print(13,'서 Necromancer님에게 반기를 들다니... 그');
                    Print(13,'것은 바로 죽음이다. 받아랏!!');
                    with player[6] do begin
                       hp := 0;
                       unconscious := 1;
                       dead := 30000;
                    end;
                    if soundon then begin
                       hit; hit;
                       delay(500); hit;
                    end;
                    SimpleDisCond;
                    PressAnyKey;
                 end;
                 battlemode(FALSE);
                 if not enemy[3].dead then begin
                    scroll(TRUE);
                    exit;
                 end;
                 party.etc[44] := party.etc[44] or bit2;
              end;
              with party do begin
                 map := 25; xaxis := 25; yaxis := 45;
              end;
              load;
           end

begin
                 Print(15,'      (25,27)에 있는 레버를 움직이면');
                 Print(15,'          성을 볼수 있을 것이오.');
                 Print(7,'');
                 Print(10,'             제작자 안 영기 씀');
                 map[25,27] := 52;
              end

begin
              if map[x,y] = 0 then exit;
              Clear;
              if y = 46 then begin
                 if wantexit then begin
                    with party do begin
                       xaxis := 34; yaxis := 15; map := 5;
                    end;
                    load;
                    scroll(TRUE);
                 end
                 else begin
                    dec(y); scroll(TRUE);
                 end;
              end;
              if y = 26 then begin
                 enemynumber := 1;
                 joinenemy(1,70);
                 with enemy[1] do begin
                    name := 'Necromancer';
                    E_number := 1;
                 end;
                 displayenemies(TRUE);
                 Print(13,' 잘도 여기까지 찾아왔구나 '+player[1].name+'.');
                 Print(13,' 네가 찾던 그 Necromancer가 바로 나다. 드디');
                 Print(13,'어 너의 실력을 보게 되겠구나. 하지만 분명히');
                 Print(13,'나보다는 떨어지겠지만. 으하하하.');
                 PressAnyKey;
                 Print(13,' 너희들은 곧 환상에 빠져들게 될 것이다.');
                 Print(13,' 나는 벌써 너희들의 약점을 파악 했지.  너희');
                 Print(13,'일행들은 항상 자신을  너무 신뢰하고 믿고 있');
                 Print(13,'더군. 그러나 그 착각은 곧 깨어질 것이다.');
                 Print(15,' 어둠의 신이여, 당신의 힘으로 이들을 환상에');
                 Print(15,'빠져 들게 하소서. 인 쿠아스 젠 ~~');
                 enemynumber := 6;
                 for i := 1 to 6 do begin
                    if player[i].name = '' then joinenemy(i,60)
                    else turn_mind(i,i);
                    enemy[i].E_number := 1;
                 end;
                 displayenemies(TRUE);
                 PressAnyKey;
                 aux := FALSE;
                 repeat
                    displayenemies(TRUE);
                    battlemode(FALSE);
                    if party.etc[6] = 255 then exit;
                    if party.etc[6] > 0 then begin
                       Clear;
                       Print(7,' 하지만 당신은 환상에서 벗어나지 못했다.');
                       PressAnyKey;
                    end
                    else aux := TRUE;
                 until aux;
                 Clear;
                 enemynumber := 1;
                 joinenemy(1,70);
                 with enemy[1] do begin
                    name := 'Necromancer';
                    E_number := 1;
                 end;
                 displayenemies(TRUE);
                 Print(13,' 환상에서 벗어나다니 대단한 의지력이군.');
                 Print(13,' 하지만 진짜 적은 바로 나다. 받아라 !!');
                 PressAnyKey;
                 battlemode(FALSE);
                 if party.etc[6] = 255 then exit;
                 if party.etc[6] > 0 then begin
                    inc(y);
                    scroll(TRUE);
                    exit;
                 end;
                 Clear;
                 Print(13,' 욱! 너의 힘은 대단하구나. 나는 너에게 졌다');
                 Print(13,'고 인정하겠다.  흐흐, 그러나 사실 나는 너희');
                 Print(13,'찾던 Necromancer님이 아니다.  만약 그분이라');
                 Print(13,'이렇게 쉽게 당하지는 않았을게니까.  내 생명');
                 Print(13,'이 얼마 안남았구나. Necromancer님 만세 !!');
                 PressAnyKey;
                 Print(7,' 그는 숨이 끊어졌고 주위의 기둥도 그와 함께');
                 Print(7,'사라져 버렸다.');
                 map[29,43] := 53;
                 for j := 25 to 27 do
                 for i := 24 to 27 do map[i,j] := 46;
                 PressAnyKey;
                 scroll(TRUE);
              end;
              if on(25,27) then begin
                 map[25,27] := 46;
                 map[29,43] := 44;
                 for j := 7 to 34 do
                 for i := 12 to 39 do
                 if map[i,j] = 0 then map[i,j] := 39;
                 for i := 25 to 26 do map[i,12] := 54;
                 Print(7,' 푯말에 쓰여 있는 대로 이 곳의 레버를 당겼 ');
                 Print(7,'더니 굉음과 함께 감추어져 있었던 성이 지하 ');
                 Print(7,'로부터 떠 올랐다.');
                 PressAnyKey;
              end;
           end
